const stt = $input.first().json || {};
const transcript = (stt.text || '').toString().trim();
const wh = $('회의웹훅').first().json || {};
const body = wh.body || {};
const title = (body.title || '회의').toString().trim();
const when = (body.when || '').toString().trim();
const host = (body.host || '').toString().trim();
const attendees = (body.attendees || '').toString().trim();
const email = (body.email || '').toString().trim();
const durationSec = parseInt(body.duration_sec || '0', 10) || 0;
const tplMd = (body.template_md || '').toString();
const DEFAULT_TPL = `# 회의록

## 회의 정보
- 제목: {title}
- 일시: {datetime}
- 진행자: {host}
- 참석자: {attendees}

## 주요 논의
(화자별 주요 발언 요약)

## 결정 사항
- (회의에서 합의·결정된 내용)

## 액션 아이템
- [ ] (담당자) 내용 (기한)

## 다음 회의
- (예정 일정 또는 미정)`;
const tpl = tplMd && tplMd.trim().length>20 ? tplMd : DEFAULT_TPL;
const sys = '당신은 전문 회의록 서기입니다. 한국어 녹음 텍스트에서 화자를 추론해 분류하고, 주어진 회의록 양식(Markdown)에 맞게 정리한 다음, 최종 회의록을 반속이고 읽기 좋은 HTML 본문만 출력합니다. <html>·<head>·<body> 태그는 쓰지 말고, 본문 마크업만 출력하세요(h1/h2/h3, ul/li, table, p 등). 설명문·코드 펜스·머릿말은 안 됩니다.';
const user = '## 회의 메타
- 제목: '+title+'
- 일시: '+(when||'(미지정)')+'
- 진행자: '+(host||'(미지정)')+'
- 참석자(힌트): '+(attendees||'(미지정)')+'
- 녹음 길이: '+durationSec+'초

## 적용할 회의록 양식(Markdown)
```
'+tpl+'
```

## 원본 음성 STT(화자 미분리 텍스트)
```
'+(transcript || '(음성 인식 결과 없음)')+'
```

[작성 지침]
1) 위 양식의 {title}/{datetime}/{host}/{attendees} 같은 플레이스홀더는 주어진 메타로 치환
2) 참석자가 주어졌으면 텍스트에서 누가 말했을지 경근대 추론해 실명으로 표기(단, 확신이 없으면 "참석자A" 식으로)
3) 주요 논의는 화자별로 채장하는 구조 유지(예: <h3>화자: 김병철</h3><ul><li>…</li></ul>)
4) 결정·액션·다음 회의는 명확하게 추출, 없으면 "(해당 없음)"
5) 출력은 오직 HTML 본문(마크업)만. 설명·앞뒤 인사 금지.';
const llmBody = { model: 'gpt-4o-mini', temperature: 0.2, messages: [ { role:'system', content: sys }, { role:'user', content: user } ] };
return [{ json:{ title, email, host, attendees, when, duration_sec: durationSec, transcript, llm_body: JSON.stringify(llmBody) } }];

const llm = $input.first().json || {};
let body = ((llm.choices && llm.choices[0] && llm.choices[0].message && llm.choices[0].message.content) || '').toString().trim();
body = body.replace(/^```(?:html)?\s*/i,'').replace(/```\s*$/,'').trim();
const meta = $('프롬프트빌드').first().json || {};
const title = meta.title || '회의록';
const dateStr = new Date().toLocaleString('ko-KR', { timeZone:'Asia/Seoul' });
const esc = s => String(s==null?'':s).replace(/[&<>"]/g, c=>({ '&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;' }[c]));
const html = ['<!DOCTYPE html>','<html lang="ko"><head><meta charset="UTF-8"><title>'+esc(title)+' 회의록</title>','<style>','body{font-family:"Pretendard","맑은 고딕",sans-serif;max-width:780px;margin:24px auto;padding:0 18px;color:#1f2a44;line-height:1.65}','h1{border-bottom:3px solid #3d7be8;padding-bottom:8px;color:#2e5fbf}','h2{margin-top:28px;color:#2e5fbf;border-left:4px solid #3d7be8;padding-left:10px}','h3{margin-top:18px;color:#34507e}','ul{padding-left:22px}li{margin:4px 0}','table{border-collapse:collapse;width:100%;margin:8px 0}','th,td{border:1px solid #dde3ee;padding:8px 10px;text-align:left}','th{background:#eef3fb;color:#2e5fbf}','.meta{background:#f5f7fb;border:1px solid #dde3ee;border-radius:10px;padding:12px 14px;margin:14px 0}','.footer{margin-top:36px;padding-top:14px;border-top:1px solid #dde3ee;color:#6b7793;font-size:.86rem}','</style></head><body>',body,'<div class="footer">📝 자동 생성 회의록 · 생성 시각: '+esc(dateStr)+' · 음성 인식: OpenAI Whisper · 요약: gpt-4o-mini</div>','</body></html>'].join('\n');
return [{ json:{ title: meta.title, email: meta.email, html, body_excerpt: body.slice(0, 300) } }];

let html='', title='', email='';
try{ const h=$('HTML조립').first().json; html=h.html||''; title=h.title||''; email=h.email||''; }catch(e){}
let email_ok=false, email_error='';
try{ const m=$('이메일전송').first(); if(m && m.json){ email_ok = !m.error; if(m.error) email_error=String(m.error.message||m.error); } }catch(e){ email_error=String(e.message||e); }
return [{ json:{ ok:true, title, email, email_ok, email_error, html } }];
